    int row = this.requestsList.getListElementIndexByPane((Pane)button);
    List<IRequest<?>> requests = this.getOpenRequests();
    if (row >= 0 && row < requests.size()) {
        this.reopenWithRequest.accept(requests.get(row));
    }
}

