public void onColonyTick(IColony colony) {
    if (this.blueprintFuture != null && this.blueprintFuture.isDone()) {
        try {
            Blueprint blueprint = this.blueprintFuture.get();
            if (blueprint != null) {
                this.blueprintFuture = null;
                if (this.recalcPrestige) {
                    this.calculatePrestige(blueprint);
                    this.recalcPrestige = false;
                }
            } else {
                this.recalcPrestige = false;
                colony.getServerBuildingManager().clearPendingPrestigeCalc(this);
            }
        }
        catch (Exception e) {
            Log.getLogger().info("Failed to load blueprintfuture for: pack:" + this.blueprintFuturePack + " name:" + this.blueprintFutureName, (Throwable)e);
            this.blueprintFuture = null;
        }
    }
}

@Override
public void asyncPrestigeRecalc() {
    if (this.buildingLevel == 0) {
        this.colony.getServerBuildingManager().clearPendingPrestigeCalc(this);
        return;
    }
    if (!this.recalcPrestige) {
        this.recalcPrestige = true;
        this.blueprintFuture = StructurePacks.getBlueprintFuture((String)this.getStructurePack(), (String)this.getBlueprintPath());
    }
}

private void unsafeUpdateTEDataFromSchematic(TileEntityColonyBuilding te) {
    String packName;
    String structureName;
    if (te.getSchematicName().isEmpty()) {
        structureName = this.path;
        packName = this.structurePack;
    } else {
        structureName = te.getBlueprintPath();
        packName = te.getStructurePack().getName();
    }
    this.blueprintFuture = StructurePacks.getBlueprintFuture((String)packName, (String)structureName);
    this.blueprintFuturePack = packName;
